#include "uploader.h"

#include <iostream>

void Uploader::upload(const Chunk &chunk)
{
    std::cout << "[DEBUG] sending chunk " << chunk.index << " (" << chunk.data.size() << " bytes)" << std::endl;
    auto res = client_.put(chunk);
    if (!res.ok()) {
        std::cout << "!!! chunk " << chunk.index << " failed status=" << res.status << std::endl;
        return;
    }
    std::cout << "chunk " << chunk.index << " ok" << std::endl;
}

