#include "uploader.h"

#include <spdlog/spdlog.h>

void Uploader::upload(const Chunk &chunk)
{
    spdlog::debug("sending chunk {} ({} bytes)", chunk.index, chunk.data.size());
    auto res = client_.put(chunk);
    if (!res.ok()) {
        spdlog::warn("chunk {} failed: status={}", chunk.index, res.status);
        return;
    }
    spdlog::info("chunk {} ok", chunk.index);
}

#include "uploader.h"

#include <spdlog/spdlog.h>

int main(int argc, char *argv[])
{
    spdlog::set_level(spdlog::level::info);
    spdlog::set_pattern("%H:%M:%S.%e [%^%l%$] %v");

    Uploader uploader(Config::load(argc, argv));
    return uploader.run();
}

